#!/bin/bash## Emind AI 鏁版嵁钂搁鑴氭湰# 鍒╃敤 DeepSeek V4 Flash 鐢熸垚 SFT 璁粌鏁版嵁锛岄浂鎴愭湰 + Teacher API 娣峰悎## 鐢ㄦ硶:#   ./run_distill.sh                                    # 榛樿鍙傛暟#   ./run_distill.sh --output ./data/my_distill         # 鑷畾涔夎緭鍑?#   ./run_distill.sh --code 5000 --reasoning 1000       # 鏇村浠ｇ爜/鎺ㄧ悊鏁版嵁#   ./run_distill.sh --workers 20                       # 鏇村骞跺彂 (榛樿10)#   EMIND_API_KEY=sk-xxx ./run_distill.sh               # 璁剧疆 API Key## 鍓嶇疆鏉′欢:#   - Python 3.10+#   - pip install requests#   - 鏈夋晥鐨?DeepSeek API Key (閫氳繃 EMIND_API_KEY 鐜鍙橀噺鎴?--api-key 浼犲叆)#set -eSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"cd "$SCRIPT_DIR"# 鈹€鈹€鈹€ 榛樿鍙傛暟 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€TEACHER_BACKEND="cloud_api"TEACHER_MODEL="deepseek-v4-flash"TEACHER_BASE_URL="https://api.deepseek.com"API_KEY="${EMIND_API_KEY:-}"CODE=3000REASONING=500DEEP_REASONING=1000ANTI_HALLUCINATION=1500IDENTITY=100OUTPUT_DIR="data/distilled/emind_code_4b"WORKERS=10MAX_TOKENS=2048TEMPERATURE=0.7# 鈹€鈹€鈹€ 鍙傛暟瑙ｆ瀽 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€while [ $# -gt 0 ]; do    case "$1" in        --code) CODE="$2"; shift 2 ;;        --reasoning) REASONING="$2"; shift 2 ;;        --deep-reasoning) DEEP_REASONING="$2"; shift 2 ;;        --anti-hallucination) ANTI_HALLUCINATION="$2"; shift 2 ;;        --identity) IDENTITY="$2"; shift 2 ;;        --output) OUTPUT_DIR="$2"; shift 2 ;;        --workers) WORKERS="$2"; shift 2 ;;        --max-tokens) MAX_TOKENS="$2"; shift 2 ;;        --temperature) TEMPERATURE="$2"; shift 2 ;;        --api-key) API_KEY="$2"; shift 2 ;;        --model) TEACHER_MODEL="$2"; shift 2 ;;        --base-url) TEACHER_BASE_URL="$2"; shift 2 ;;        --help|-h)            echo "鐢ㄦ硶: $0 [閫夐」]"            echo ""            echo "鏁版嵁閲?"            echo "  --code NUM              浠ｇ爜鏍锋湰鏁?(榛樿: 3000)"            echo "  --reasoning NUM         鎺ㄧ悊鏍锋湰鏁?(榛樿: 500)"            echo "  --deep-reasoning NUM    娣卞害鎺ㄧ悊鏍锋湰鏁?(榛樿: 1000)"            echo "  --anti-hallucination NUM 鍙嶅够瑙夋牱鏈暟 (榛樿: 1500)"            echo "  --identity NUM          韬唤璁ょ煡鏍锋湰鏁?(榛樿: 100)"            echo ""            echo "Teacher 妯″瀷:"            echo "  --api-key KEY           DeepSeek API Key (鎴?EMIND_API_KEY 鐜鍙橀噺)"            echo "  --model NAME            妯″瀷鍚?(榛樿: deepseek-v4-flash)"            echo "  --base-url URL          API 鍦板潃 (榛樿: https://api.deepseek.com)"            echo ""            echo "鐢熸垚鍙傛暟:"            echo "  --max-tokens NUM        鏈€澶х敓鎴?token 鏁?(榛樿: 2048)"            echo "  --temperature TEMP      鐢熸垚娓╁害 (榛樿: 0.7)"            echo "  --workers NUM           骞跺彂 API 绾跨▼鏁?(榛樿: 10)"            echo "  --output DIR            杈撳嚭鐩綍 (榛樿: data/distilled/emind_code_4b)"            echo ""            echo "鐜鍙橀噺:"            echo "  EMIND_API_KEY           DeepSeek API Key"            exit 0            ;;        *) echo "鏈煡鍙傛暟: $1"; exit 1 ;;    esacdoneif [ -z "$API_KEY" ]; then    echo "閿欒: 鏈缃?API Key"    echo "璇烽€氳繃 --api-key 鍙傛暟鎴?EMIND_API_KEY 鐜鍙橀噺璁剧疆"    exit 1fi# 鈹€鈹€鈹€ 鎵撳嵃閰嶇疆 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€echo "=========================================="echo " Emind AI 鏁版嵁钂搁"echo "=========================================="echo " Teacher:   $TEACHER_MODEL ($TEACHER_BASE_URL)"echo " 浠ｇ爜:      $CODE"echo " 鎺ㄧ悊:      $REASONING"echo " 娣卞害鎺ㄧ悊:  $DEEP_REASONING"echo " 鍙嶅够瑙?    $ANTI_HALLUCINATION"echo " 韬唤璁ょ煡:  $IDENTITY"echo " 杈撳嚭:      $OUTPUT_DIR"echo " 骞跺彂:      $WORKERS"echo "=========================================="echo ""# 鈹€鈹€鈹€ 杩愯钂搁 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€python -u cli.py pipeline \    --distill-code "$CODE" \    --distill-reasoning "$REASONING" \    --distill-deep-reasoning "$DEEP_REASONING" \    --distill-anti-hallucination "$ANTI_HALLUCINATION" \    --distill-identity "$IDENTITY" \    --teacher-backend "$TEACHER_BACKEND" \    --teacher-api-key "$API_KEY" \    --teacher-model "$TEACHER_MODEL" \    --teacher-base-url "$TEACHER_BASE_URL" \    --distill-output "$OUTPUT_DIR" \    --max-new-tokens "$MAX_TOKENS" \    --temperature "$TEMPERATURE"echo ""echo "鉁?钂搁瀹屾垚锛佽緭鍑烘枃浠? $OUTPUT_DIR/distilled_sft.jsonl"echo "  鍚庣画鍙敤浠ヤ笅鍛戒护寮€濮?SFT 璁粌:"echo "    python cli.py train --mode sft --data $OUTPUT_DIR/distilled_sft.jsonl"